    if op.get_bind().dialect.name == "postgresql":
        for name in (
            "coverage_verdict",
            "attempt_state",
            "run_merge_status",
            "run_freshness",
            "run_verdict",
            "run_execution_state",
        ):
            ENUM(name=name).drop(op.get_bind(), checkfirst=False)
